SELECT s1.`c0` AS `x` FROM (SELECT s2.`c0` AS `c0` FROM (SELECT s3.`c1` AS `c0` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1` FROM (SELECT v.`c0` AS `c0`, v.`c1` AS `c1` FROM (VALUES (CAST(1 AS BIGINT), CAST(10 AS BIGINT)), (CAST(1 AS BIGINT), CAST(30 AS BIGINT)), (CAST(2 AS BIGINT), CAST(20 AS BIGINT)), (CAST(NULL AS BIGINT), CAST(40 AS BIGINT)), (CAST(2 AS BIGINT), CAST(NULL AS BIGINT)), (CAST(1 AS BIGINT), CAST(5 AS BIGINT))) AS v(`c0`, `c1`)) AS s4 WHERE ((NOT (s4.`c0` IS NULL)) IS TRUE)) AS s3) AS s2 LIMIT 2 OFFSET 1) AS s1
